param([Parameter(Mandatory=$true)][string]$SavePath)
# Read-only XML extraction. No game code, save mutation, default verb state or hit model.
$ErrorActionPreference='Stop'
$s=[xml](Get-Content -Raw -LiteralPath $SavePath)
function Number($n,[string]$field){$v=$n.SelectSingleNode($field);[ordered]@{present=($null -ne $v);value=if($v){[double]::Parse($v.InnerText,[Globalization.CultureInfo]::InvariantCulture)}else{$null}}}
function Flag($n,[string]$field){$v=$n.SelectSingleNode($field);[ordered]@{present=($null -ne $v);value=if($v){$v.InnerText -eq 'True'}else{$null}}}
function Raw($n,[string]$field){$v=$n.SelectSingleNode($field);if($v){$v.OuterXml}else{$null}}
function Injury($n){[ordered]@{id=[int]$n.loadID;class=[string]$n.Class;def=[string]$n.def;body=[string]$n.part.body;part_index=(Number $n 'part/index');severity=(Number $n 'severity');tick_added=(Number $n 'tickAdded');age_ticks=(Number $n 'ageTicks');permanent=(Flag $n 'isPermanent');combat_log_entry=[string]$n.combatLogEntry;raw=$n.OuterXml}}
function Weapon($n){[ordered]@{id=[string]$n.id;def=[string]$n.def;pos=[string]$n.pos;hp=(Number $n 'health');quality=[string]$n.quality;quality_present=($null -ne $n.SelectSingleNode('quality'));owner=[string]$n.SelectSingleNode('ancestor::*[def="Human"][1]/id').InnerText;despawned_tick=(Number $n 'despawnedTick');spawned_tick=(Number $n 'spawnedTick');verbs=@($n.SelectNodes('verbTracker/verbs/li')|ForEach-Object{[ordered]@{class=[string]$_.Class;load_id=[string]$_.loadID;state=[string]$_.state;state_present=($null -ne $_.SelectSingleNode('state'));last_shot_tick=(Number $_ 'lastShotTick');burst_shots_left=(Number $_ 'burstShotsLeft');ticks_to_next_burst_shot=(Number $_ 'ticksToNextBurstShot');target=[string]$_.currentTarget;raw=$_.OuterXml}});raw=$n.OuterXml}}
$map=$s.SelectSingleNode('//thing[id="Human965"]').ParentNode.ParentNode
$pawns=@($map.SelectNodes('./things/thing[def="Human" or def="Muffalo"]')|ForEach-Object{
 $p=$_
 [ordered]@{id=[string]$p.id;def=[string]$p.def;nick=[string]$p.name.nick;pos=[string]$p.pos;health_state=[string]$p.healthTracker.healthState;drafted=(Flag $p 'drafter/drafted');drafter=(Raw $p 'drafter');mental_state=(Raw $p 'mindState/mentalStateHandler');medical_care=[string]$p.playerSettings.medCare;self_tend=(Flag $p 'playerSettings/selfTend');work_priorities=(Raw $p 'workSettings/priorities');hediffs=@($p.SelectNodes('healthTracker/hediffSet/hediffs/li')|ForEach-Object{Injury $_});job=(Raw $p 'jobs/curJob');job_driver=(Raw $p 'jobs/curDriver');stance=(Raw $p 'stances/curStance');pather=(Raw $p 'pather');equipment_ids=@($p.SelectNodes('equipment/equipment/innerList/li/id')|ForEach-Object{$_.InnerText});skills=@($p.SelectNodes('skills/skills/li')|ForEach-Object{[ordered]@{def=[string]$_.def;level=(Number $_ 'level');xp_since_level=(Number $_ 'xpSinceLastLevel');xp_since_midnight=(Number $_ 'xpSinceMidnight');passion=[string]$_.passion}});traits=(Raw $p 'story/traits');apparel=@($p.SelectNodes('apparel/wornApparel/innerList/li')|ForEach-Object{[ordered]@{id=[string]$_.id;def=[string]$_.def;hp=(Number $_ 'health');quality=[string]$_.quality;stuff=[string]$_.stuff}})}
}|Sort-Object {$_.id})
[ordered]@{
 file=(Split-Path -Leaf $SavePath);sha256=(Get-FileHash -LiteralPath $SavePath -Algorithm SHA256).Hash.ToLowerInvariant();bytes=(Get-Item -LiteralPath $SavePath).Length
 version=$s.SelectSingleNode('//meta/gameVersion').InnerText;mods=@($s.SelectNodes('//meta/modIds/li')|ForEach-Object{$_.InnerText});tick=[int]$s.SelectSingleNode('//tickManager/ticksGame').InnerText;tick_manager_raw=$s.SelectSingleNode('//tickManager').OuterXml
 pawns=$pawns;weapons=@($map.SelectNodes('.//*[id and (starts-with(def,"Gun_") or starts-with(def,"Bow_"))]')|ForEach-Object{Weapon $_}|Sort-Object {$_.id})
 projectiles=@($map.SelectNodes('./things/thing[launcher or ticksToImpact or starts-with(def,"Bullet_") or starts-with(def,"Arrow_")]')|ForEach-Object{[ordered]@{id=[string]$_.id;def=[string]$_.def;raw=$_.OuterXml}})
 battle_entries=@($s.SelectNodes('//battleLog/battles/li/entries/li[logID>42]')|ForEach-Object{[ordered]@{id=[int]$_.logID;class=[string]$_.Class;ticks_abs=(Number $_ 'ticksAbs');raw=$_.OuterXml}}|Sort-Object {$_.id})
 cover=@($map.SelectNodes('./things/thing[def="Wall" or def="Sandbags"]')|ForEach-Object{[ordered]@{id=[string]$_.id;def=[string]$_.def;pos=[string]$_.pos;hp=(Number $_ 'health');stuff=[string]$_.stuff}}|Sort-Object {$_.id})
 scope='Read-only current map Humans/Muffalo, weapons including equipped items, projectile records, walls/sandbags and new battle entries after inherited log42. Optional numeric/bool fields retain explicit presence and null absence. Raw stances, verbs, jobs, projectile and battle XML permit offline inspection without inferred default states. ticksAbs and ticksGame are distinct clocks. No OCR, computed hit chances, capacities or health labels are inserted.'
}|ConvertTo-Json -Depth 30
